import json, zipfile
with zipfile.ZipFile('semio/assets/semio/metabolism.zip') as z:
    print('Files:', z.namelist()[:10])
    for name in z.namelist():
        if name.endswith('.json') and 'kit' in name.lower():
            with z.open(name) as f:
                data = json.load(f)
                if 'designs' in data:
                    for d in data['designs'][:3]:
                        print('Design:', d.get('name'), 'guid:', d.get('guid'), 
                              'parent:', d.get('parent'), 
                              'concepts:', d.get('concepts', [])[:2])
                if 'types' in data:
                    for t in data['types'][:3]:
                        print('Type:', t.get('name'), 'guid:', t.get('guid'),
                              'parent:', t.get('parent'))
            break
" 2>&1 | head -30

