const { chromium } = require('@playwright/test');
const path = require('path');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const errors = [];
  page.on('console', msg => {
    if (msg.type() === 'error') errors.push(msg.text().substring(0, 300));
  });
  page.on('pageerror', err => errors.push('PAGEERROR: ' + err.message.substring(0, 300)));

  // Go to home
  await page.goto('http://localhost:5173/');
  await page.waitForTimeout(3000);

  // Import kit
  const fileInput = page.locator('[id=\"semio.sketchpad.app.home.importKit\"]');
  await fileInput.setInputFiles(path.resolve('..', 'assets/semio/metabolism.zip'));
  await fileInput.evaluate(el => el.dispatchEvent(new Event('change', { bubbles: true })));

  // Wait for Metabolism
  const metabolismText = page.getByText('Metabolism', { exact: true }).first();
  await metabolismText.waitFor({ state: 'visible', timeout: 60000 });

  // Navigate to kit
  const tableRow = page.locator('tr[data-row-id]').filter({ hasText: 'Metabolism' }).first();
  const isVisible = await tableRow.isVisible().catch(() => false);
  if (isVisible) {
    await tableRow.dblclick({ force: true });
  } else {
    await metabolismText.dblclick({ force: true });
  }

  await page.waitForURL(/.*kits\/.+/, { timeout: 30000 });
  console.log('Kit URL:', page.url());
  await page.waitForTimeout(5000);

  // Click selection group toggle
  const selGroupToggle = page.locator('[id=\"semio.sketchpad.toolbar.group.selection\"]');
  const hasSelGroup = await selGroupToggle.isVisible({ timeout: 5000 }).catch(() => false);
  console.log('Selection group visible:', hasSelGroup);

  if (hasSelGroup) {
    await selGroupToggle.click();
    await page.waitForTimeout(2000);

    const settingsZone = page.locator('[id=\"semio.sketchpad.toolbar.zone.settings\"]');
    const hasSettings = await settingsZone.isVisible({ timeout: 3000 }).catch(() => false);
    console.log('Settings zone visible:', hasSettings);

    // Get content of settings zone
    const settingsContent = await settingsZone.innerHTML().catch(() => '');
    console.log('Settings HTML (first 500):', settingsContent.substring(0, 500));

    const intersect = page.locator('[id=\"semio.sketchpad.app.kit.tools.select.mode.intersect\"]');
    const hasIntersect = await intersect.isVisible({ timeout: 3000 }).catch(() => false);
    console.log('Intersect visible:', hasIntersect);
  }

  console.log('Errors:', JSON.stringify(errors.slice(0, 10)));
  await browser.close();
})().catch(e => console.error(e));
" 2>&1

