const { chromium } = require('@playwright/test');
const path = require('path');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:5173/');
  await page.waitForTimeout(3000);
  const fileInput = page.locator('[id=\"semio.sketchpad.app.home.importKit\"]');
  await fileInput.setInputFiles(path.resolve('..', 'assets/semio/metabolism.zip'));
  await fileInput.evaluate(el => el.dispatchEvent(new Event('change', { bubbles: true })));
  const mt = page.getByText('Metabolism', { exact: true }).first();
  await mt.waitFor({ state: 'visible', timeout: 60000 });
  const tr = page.locator('tr[data-row-id]').filter({ hasText: 'Metabolism' }).first();
  const v = await tr.isVisible().catch(() => false);
  if (v) await tr.dblclick({ force: true });
  else await mt.dblclick({ force: true });
  await page.waitForURL(/.*kits\/.+/, { timeout: 30000 });
  await page.waitForTimeout(5000);

  // Activate selection group
  const selGroup = page.locator('[id=\"semio.sketchpad.toolbar.group.selection\"]');
  await selGroup.click();
  await page.waitForTimeout(1000);

  const additive = page.locator('[id=\"semio.sketchpad.app.kit.tools.select.mode.additive\"]');

  // Check all attributes before click
  const beforeAttrs = await additive.evaluate(el => {
    const attrs = {};
    for (const a of el.attributes) attrs[a.name] = a.value;
    return attrs;
  });
  console.log('Before click:', JSON.stringify(beforeAttrs));

  // Click the additive toggle
  await additive.click();
  await page.waitForTimeout(500);

  // Check all attributes after click
  const afterAttrs = await additive.evaluate(el => {
    const attrs = {};
    for (const a of el.attributes) attrs[a.name] = a.value;
    return attrs;
  });
  console.log('After click:', JSON.stringify(afterAttrs));

  // Also check the inner button
  const innerBtn = additive.locator('button').first();
  const innerCount = await innerBtn.count();
  if (innerCount > 0) {
    const innerAttrs = await innerBtn.evaluate(el => {
      const attrs = {};
      for (const a of el.attributes) attrs[a.name] = a.value;
      return attrs;
    });
    console.log('Inner button attrs:', JSON.stringify(innerAttrs));
  }

  await browser.close();
})().catch(e => console.error(e));
" 2>&1

