const { chromium } = require('@playwright/test');
const path = require('path');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', err => errors.push('PAGEERROR: ' + err.message.substring(0, 300) + ' STACK: ' + (err.stack||'').substring(0, 300)));

  await page.goto('http://localhost:5173/');
  await page.waitForTimeout(3000);
  const fileInput = page.locator('[id=\"semio.sketchpad.app.home.importKit\"]');
  await fileInput.setInputFiles(path.resolve('..', 'assets/semio/metabolism.zip'));
  await fileInput.evaluate(el => el.dispatchEvent(new Event('change', { bubbles: true })));
  const mt = page.getByText('Metabolism', { exact: true }).first();
  await mt.waitFor({ state: 'visible', timeout: 60000 });
  const tr = page.locator('tr[data-row-id]').filter({ hasText: 'Metabolism' }).first();
  const v = await tr.isVisible().catch(() => false);
  if (v) await tr.dblclick({ force: true });
  else await mt.dblclick({ force: true });
  await page.waitForURL(/.*kits\/.+/, { timeout: 30000 });
  await page.waitForTimeout(3000);

  const designRow = page.locator('tr[data-row-id^=\"design-\"]').first();
  await designRow.dblclick({ force: true });
  await page.waitForURL(/.*designs\/.+/, { timeout: 30000 });
  await page.waitForTimeout(10000);

  console.log('URL:', page.url());
  const diagramEl = page.locator('#diagram .react-flow').first();
  const hasDiagram = await diagramEl.isVisible({ timeout: 5000 }).catch(() => false);
  console.log('Diagram visible:', hasDiagram);

  const navbar = page.locator('[id=\"semio.sketchpad.navbar\"]');
  const hasNavbar = await navbar.isVisible({ timeout: 5000 }).catch(() => false);
  console.log('Navbar visible:', hasNavbar);

  const bodyText = await page.evaluate(() => document.body.innerText.substring(0, 300));
  console.log('Body text:', bodyText);

  const diagramDiv = await page.locator('#diagram').count();
  console.log('#diagram count:', diagramDiv);

  const rfCount = await page.locator('.react-flow').count();
  console.log('.react-flow count:', rfCount);

  for (const e of errors.slice(0, 5)) console.log(e);
  await browser.close();
})().catch(e => console.error(e));
" 2>&1

