  if (v) await tr.dblclick({ force: true });
  else await mt.dblclick({ force: true });
  await page.waitForURL(/.*kits\/.+/, { timeout: 30000 });
  await page.waitForTimeout(3000);

  const designRow = page.locator("tr[data-row-id^=\"design-\"]").first();
