**Toggle Handler** [Line 4324](semio/sketchpad/sketchpad/Kit.tsx#L4324):
```typescript
const toggleKind = (kind: ArtifactKind) => {
  const newParams = new URLSearchParams(searchParams);
  const kinds = newParams.getAll("kind") as ArtifactKind[];

  if (kinds.length === 0) {
    newParams.append("kind", kind);  // First: select ONLY this kind
  } else if (kinds.includes(kind)) {
    const remaining = kinds.filter((k) => k !== kind);
    newParams.delete("kind");
    remaining.forEach((k) => newParams.append("kind", k));  // Remove
  } else {
    newParams.append("kind", kind);  // Add to selection
  }
  setSearchParams(newParams);
};
```

